        for c in r:
            dc = demand(c)
            if cur and cur_load + dc > capacity:
                repaired.append(cur)
                cur = [c]
                cur_load = dc
            else:
                cur.append(c)
                cur_load += dc
        if cur:
            repaired.append(cur)
    routes = repaired

    # ---------- local search: intra-route 2-opt ----------
    def two_opt(route):
        if len(route) < 4:
            return route[:]
        best = route[:]
        best_cost = route_cost(best)
        improved = True
        while improved:
            improved = False
            n = len(best)
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    cand = best[:i + 1] + best[i + 1:j + 1][::-1] + best[j + 1:]
                    cand_cost = route_cost(cand)
                    if cand_cost + 1e-12 < best_cost:
                        best = cand
                        best_cost = cand_cost
                        improved = True
                        break
                if improved:
                    break
        return best

    routes = [two_opt(r) for r in routes]

    # ---------- repair/improvement: relocate between routes ----------
    # Move customers from overloaded/long routes to feasible positions if it helps.
    changed = True
    while changed:
        changed = False
        route_loads = [route_load(r) for r in routes]
        for i in range(len(routes)):
            r1 = routes[i]
            if not r1:
                continue
            base1 = route_cost(r1)
            best_move = None  # (gain, j, idx, insertion_pos, new_r1, new_r2)
            for idx, c in enumerate(r1):
                dc = demand(c)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    r2 = routes[j]
                    if route_loads[j] + dc > capacity:
                        continue
                    # removal from r1
                    r1_removed = r1[:idx] + r1[idx + 1:]
                    # try best insertion in r2
                    best_ins_cost = None
                    best_ins_route = None
                    if not r2:
                        cand2 = [c]
                        best_ins_cost = route_cost(cand2)
                        best_ins_route = cand2
                    else:
                        for pos in range(len(r2) + 1):
                            cand2 = r2[:pos] + [c] + r2[pos:]
                            cc = route_cost(cand2)
                            if best_ins_cost is None or cc < best_ins_cost:
                                best_ins_cost = cc
                                best_ins_route = cand2
                    new_cost = route_cost(r1_removed) + best_ins_cost
                    old_cost = base1 + route_cost(r2)
                    gain = old_cost - new_cost
                    if gain > 1e-12 and (best_move is None or gain > best_move[0] or (gain == best_move[0] and (j, idx) < (best_move[1], best_move[2]))):
                        best_move = (gain, j, idx, r1_removed, best_ins_route)
            if best_move is not None:
                _, j, idx, new_r1, new_r2 = best_move
                routes[i] = new_r1
                routes[j] = new_r2
                changed = True
                break

    # Remove empties and final 2-opt
    routes = [r for r in routes if r]
    routes = [two_opt(r) for r in routes if r]

    # ---------- final feasibility pass: ensure every customer exactly once ----------
    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = [c for c in customers if seen.get(c, 0) == 0]
    dupes = [c for c, k in seen.items() if k > 1]

    if missing or dupes:
        # Build a clean solution from scratch using capacity-aware greedy insertion.
        remaining = sorted(customers, key=lambda c: (demand(c), dist(depot, c), c))
        clean = []
        for c in remaining:
            dc = demand(c)
            best_i = None
            best_delta = None
            for i, r in enumerate(clean):
                if route_load(r) + dc > capacity:
                    continue
                # best insertion position in current route
                base = route_cost(r)
                best_pos_delta = None
                for pos in range(len(r) + 1):
                    cand = r[:pos] + [c] + r[pos:]
                    delta = route_cost(cand) - base
                    if best_pos_delta is None or delta < best_pos_delta or (delta == best_pos_delta and pos < 0):
                        best_pos_delta = delta
                if best_pos_delta is not None and (best_delta is None or best_pos_delta < best_delta or (best_pos_delta == best_delta and i < best_i)):
                    best_delta = best_pos_delta
                    best_i = i
            if best_i is None:
                clean.append([c])
            else:
                r = clean[best_i]
                base = route_cost(r)
                best_pos = 0
                best_pos_delta = None
                for pos in range(len(r) + 1):
                    cand = r[:pos] + [c] + r[pos:]
                    delta = route_cost(cand) - base
                    if best_pos_delta is None or delta < best_pos_delta:
                        best_pos_delta = delta
                        best_pos = pos
                clean[best_i] = r[:best_pos] + [c] + r[best_pos:]
        routes = [two_opt(r) for r in clean if r]

    # Final capacity assert-by-construction not throwing; just keep feasible routes
    final_routes = []
    for r in routes:
        cur = []
        cur_load = 0
        for c in r:
            dc = demand(c)
            if cur and cur_load + dc > capacity:
                final_routes.append(cur)
                cur = [c]
                cur_load = dc
            else:
                cur.append(c)
                cur_load += dc
        if cur:
            final_routes.append(cur)

    return [r for r in final_routes if r]
